        "simpleMeaning": "Jibrīl asked the Prophet ﷺ: \"What is iḥsān?\" He ﷺ replied: \"Iḥsān is to worship Allah as though you see Him. For if you do not see Him, He surely sees you.\"",
        "significance": "",
