        "work": "*Explanation of the 99 Names*",
        "view": "\"The All-Seeing, the one who sees everything such that nothing whatsoever is hidden from Him.\" His sight encompasses both visible and hidden realities, the apparent and the innermost, simultaneously and without limit.",
        "source": "Open sourcehttps://abdurrahman.org/wp-content/uploads/2018/01/the-99-names-of-allaah-dawud-burbank.pdf"
