        "view": "\"The One who guides the servants that they should repent to Him, grants to them that they should repent, and accepts their repentance again and again.\" He adds: \"This is evidence of Allah's happiness with the repentance of His slave — not due to His need, but because He loves Generosity and loves to Pardon and Forgive.\"",
