        "view": "Al-Sa'di notes that al-Haseeb includes the meaning of sufficiency (kifaayah): whoever relies upon Allah and entrusts his affairs to Him, Allah will be sufficient for him in all circumstances — combining the reckoning-aspect and the provision-aspect of the name.",
        "source": "Open sourcehttps://abdurrahman.org/wp-content/uploads/2018/01/the-99-names-of-allaah-dawud-burbank.pdf"
