        "scholar": "Shaykh Ibn al-'Uthaymeen",
        "work": "*Explanation of the 99 Names*",
        "view": "\"The True One, the one true and certain in His existence, in His self, in His attributes, in His sayings and in His actions.\" Everything else has a contingent or borrowed existence, but Allah's existence and attributes are necessarily real, without possibility of falsehood or nullity.",
        "source": "Open sourcehttps://abdurrahman.org/wp-content/uploads/2018/01/the-99-names-of-allaah-dawud-burbank.pdf"
