        "work": "*Explanation of the 99 Names*",
        "view": "\"The All-Wise, the one fully wise in everything He decrees, and fully wise in His sayings and in His actions. There is no deficiency or error in anything He decrees, says or does.\" Wisdom (hikmah) here means both knowledge of the right course and perfect execution of it.",
        "source": "Open sourcehttps://abdurrahman.org/wp-content/uploads/2018/01/the-99-names-of-allaah-dawud-burbank.pdf"
