        "view": "\"The Self-Subsisting One Upon Whom Everything Depends, the one who sustains everything that exists, the one who has no need of anything but rather everything in existence has total need of Him.\" Al-Qayyoom comprehensively affirms divine independence and universal creaturely dependence.",
