      "When Ibrāhīm and Ismāʿīl ﷺ were building the Kaʿbah — the most sacred act of their lives — they still asked: \"Accept from us. Indeed You are As-Samīʿ, Al-ʿAlīm.\" Even prophets asked As-Samīʿ to accept.",
