      "Strengthen your claim to Allah’s special friendship: increase your obedience, avoid major sins, make dhikr, and prioritize His pleasure over people’s approval. Ask yourself: “Would a friend treat Allah this way?” Then act as a loyal friend of Al‑Walī to taste His wilāyah.",
